<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ExternalLink, Plus, RefreshCw, ShieldOff } from 'lucide-vue-next'
import { api, apiError } from '../api/client';import type { ApiResponse, Paginated, Receivable } from '../types'
import PageHeader from '../components/PageHeader.vue';import DrawerPanel from '../components/DrawerPanel.vue';import InlineAlert from '../components/InlineAlert.vue';import KeyReveal from '../components/KeyReveal.vue';import StatusBadge from '../components/StatusBadge.vue';import EmptyState from '../components/EmptyState.vue'
interface Link{id:string;receivable_id:string;token_prefix:string;expires_at?:string;max_views?:number;view_count:number;last_viewed_at?:string;is_active:boolean;created_at:string}
const items=ref<Link[]>([]),receivables=ref<Receivable[]>([]),drawer=ref(false),error=ref(''),success=ref(''),reveal=ref('');const form=reactive({receivable_id:'',expires_at:'',max_views:''})
const money=(v:string)=>Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
async function load(){try{const [l,r]=await Promise.all([api.get<ApiResponse<Link[]>>('/v1/payment-links'),api.get<Paginated<Receivable>>('/v1/receivables',{params:{per_page:500}})]);items.value=l.data.data;receivables.value=r.data.data}catch(e){error.value=apiError(e)}}
function open(){form.receivable_id=receivables.value.find(x=>!['PAID','CANCELLED'].includes(x.status))?.id||'';form.expires_at='';form.max_views='';drawer.value=true}
async function create(){try{const r=(await api.post<ApiResponse<{url:string}>>('/v1/payment-links',{receivable_id:form.receivable_id,expires_at:form.expires_at||null,max_views:form.max_views?Number(form.max_views):null})).data.data;drawer.value=false;reveal.value=r.url;await load()}catch(e){error.value=apiError(e)}}
async function deactivate(item:Link){if(!confirm('Desativar este link?'))return;try{await api.delete(`/v1/payment-links/${item.id}`);await load()}catch(e){error.value=apiError(e)}}
onMounted(load)
</script>
<template><PageHeader title="Links de pagamento" subtitle="Portal público para segunda via, boleto e Pix sem exigir login do pagador."><button class="btn-secondary" @click="load"><RefreshCw :size="18"/>Atualizar</button><button class="btn-primary" @click="open"><Plus :size="18"/>Novo link</button></PageHeader><InlineAlert :message="error" @dismiss="error=''"/><InlineAlert :message="success" type="success" @dismiss="success=''"/><div class="table-wrap"><table class="table"><thead><tr><th>Recebível</th><th>Referência</th><th>Acessos</th><th>Expiração</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.id" class="border-t border-slate-100"><td><p class="font-semibold">{{receivables.find(x=>x.id===item.receivable_id)?.document_number||item.receivable_id}}</p><p class="text-xs text-slate-400">{{receivables.find(x=>x.id===item.receivable_id)?money(receivables.find(x=>x.id===item.receivable_id)!.balance):''}}</p></td><td class="font-mono text-xs">{{item.token_prefix}}…</td><td>{{item.view_count}} / {{item.max_views||'∞'}}<p class="text-xs text-slate-400">{{item.last_viewed_at?new Date(item.last_viewed_at).toLocaleString('pt-BR'):'Nunca acessado'}}</p></td><td>{{item.expires_at?new Date(item.expires_at).toLocaleString('pt-BR'):'Sem expiração'}}</td><td><StatusBadge :status="item.is_active?'ACTIVE':'INACTIVE'"/></td><td><div class="flex justify-end gap-1"><button class="btn-secondary px-3 py-2" disabled title="Por segurança, o token completo só é exibido na criação"><ExternalLink :size="16"/></button><button v-if="item.is_active" class="btn-secondary px-3 py-2 text-rose-600" @click="deactivate(item)"><ShieldOff :size="16"/></button></div></td></tr></tbody></table><EmptyState v-if="!items.length" title="Nenhum link público"/></div><DrawerPanel :open="drawer" title="Novo link de pagamento" width="lg" @close="drawer=false"><form class="space-y-4" @submit.prevent="create"><div><label class="label">Recebível</label><select v-model="form.receivable_id" class="select" required><option v-for="r in receivables.filter(x=>!['PAID','CANCELLED','REVERSED'].includes(x.status))" :key="r.id" :value="r.id">{{r.document_number}} · {{money(r.balance)}} · {{r.status}}</option></select></div><div class="grid gap-4 sm:grid-cols-2"><div><label class="label">Expiração</label><input v-model="form.expires_at" type="datetime-local" class="input"/></div><div><label class="label">Máximo de acessos</label><input v-model="form.max_views" type="number" min="1" class="input" placeholder="Ilimitado"/></div></div><div class="rounded-xl bg-sky-50 p-3 text-xs text-sky-800">O token completo será exibido uma única vez. O portal mascara o documento do pagador.</div><div class="flex justify-end gap-2"><button type="button" class="btn-secondary" @click="drawer=false">Cancelar</button><button class="btn-primary">Criar link</button></div></form></DrawerPanel><KeyReveal :open="!!reveal" :value="reveal" title="Link de pagamento criado" description="Copie e envie ao cliente. O endereço completo não poderá ser recuperado depois." @close="reveal=''"/></template>
